#!/bin/bash
# Money helpers shared by the receipt and the reports.
# round_tenth: 10% off, rounded down (amount in cents).
round_tenth() { echo $(( ($1 * 9 + 9) / 10 )); }
# cents_to_yen: display helper.
cents_to_yen() { echo "$(( $1 / 100 )).$(( $1 % 100 ))"; }

#!/bin/bash
# Receipt lines. The member line shows the member price (10% off, rounded down).
source "$(dirname "$0")/../lib/util/money.sh" 2>/dev/null || source lib/util/money.sh
member_line() { echo "receipt $(round_tenth "$1")"; }
guest_line() { echo "receipt $1"; }

./bin/receipt:5:if [ "$2" = guest ]; then guest_line "$1"; else member_line "$1"; fi
./lib/util/money.sh:3:# round_tenth: 10% off, rounded down (amount in cents).
./lib/util/money.sh:4:round_tenth() { echo $(( ($1 * 9 + 9) / 10 )); }
./lib/receipt/line.sh:3:source "$(dirname "$0")/../lib/util/money.sh" 2>/dev/null || source lib/util/money.sh
./lib/receipt/line.sh:4:member_line() { echo "receipt $(round_tenth "$1")"; }
999: 900 quote: 900 member total 900 900
1: 1 quote: 1 member total 1 1
5: 5 quote: 5 member total 5 5
10: 9 quote: 9 member total 9 9
11: 10 quote: 10 member total 10 10

